// Format phone number to international Pakistani standard (923XXXXXXXXX)
const raw = $input.first().json;
const data = raw.data || raw;

let phone = (data.customer ? data.customer.phone : data.phone) || '';
phone = phone.replace(/[^0-9]/g, '');

if (phone.startsWith('03')) {
  phone = '92' + phone.substring(1);
} else if (phone.startsWith('3') && phone.length === 10) {
  phone = '92' + phone;
}

let itemsSummary = '';
if (Array.isArray(data.items)) {
  itemsSummary = data.items.map(it => `${it.name} x${it.quantity}`).join(', ');
} else {
  itemsSummary = data.items_summary || 'Fresh Bakery Items';
}

const orderNumber = data.order_number || ('FB-' + (data.order_id || '1001'));
const totalAmount = String((data.financials ? data.financials.total_amount : data.total) || 0);
const customerName = (data.customer ? data.customer.name : data.customer_name) || 'Customer';
const address = data.delivery_address || data.address || 'Bakery Counter';

return {
  json: {
    clean_phone: phone,
    order_number: orderNumber,
    customer_name: customerName,
    items_summary: itemsSummary,
    total_amount: totalAmount,
    delivery_address: address
  }
};

